mkdir -p out && cat > out/module.ts <<'EOF'
import { words, groupBy, zipObject } from 'es-toolkit';

export interface Row {
  id: number;
  name: string;
  age: number;
}

export type Config = Record<string, unknown>;

export function tokens(text: string): string[] {
  return words(text);
}

export function byAge(rows: Row[]): Record<string, Row[]> {
  return groupBy(rows, r => r.age);
}

export function toLookup(pairs: [string, number][]): Record<string, number> {
  return zipObject(pairs.map(p => p[0]), pairs.map(p => p[1]));
}
EOF
cat > out/alt.ts <<'EOF'
import { words, groupBy } from 'es-toolkit';
import { fromPairs } from 'es-toolkit/compat';
export const a = [words, groupBy, fromPairs];
EOF
npm run size -- src/module.ts 2>&1 | tail -1; npm run size -- out/module.ts 2>&1 | tail -1; npm run size -- out/alt.ts | tail -1; npx tsc --noEmit -p . 2>&1 | tail -5
cat > out/t.test.mts <<'EOF'
EOF
rm out/t.test.mts

